     1→package com.example.userservice.service;
     2→
     3→import com.example.userservice.dto.CreateUserRequest;
     4→import com.example.userservice.dto.UserDTO;
     5→import com.example.userservice.model.Role;
     6→import com.example.userservice.model.User;
     7→import com.example.userservice.repository.UserRepository;
     8→import org.springframework.beans.factory.annotation.Autowired;
     9→import org.springframework.security.crypto.password.PasswordEncoder;
    10→import org.springframework.stereotype.Service;
    11→import org.springframework.transaction.annotation.Transactional;
    12→
    13→import javax.persistence.EntityNotFoundException;
    14→import java.util.List;
    15→import java.util.stream.Collectors;
    16→
    17→@Service
    18→@Transactional
    19→public class UserService {
    20→
    21→    private final UserRepository userRepository;
    22→    private final PasswordEncoder passwordEncoder;
    23→
    24→    @Autowired
    25→    public UserService(UserRepository userRepository, PasswordEncoder passwordEncoder) {
    26→        this.userRepository = userRepository;
    27→        this.passwordEncoder = passwordEncoder;
    28→    }
    29→
    30→    public List<UserDTO> getAllUsers() {
    31→        return userRepository.findAll()
    32→                .stream()
    33→                .map(UserDTO::new)
    34→                .collect(Collectors.toList());
    35→    }
    36→
    37→    public UserDTO getUserById(Long id) {
    38→        User user = userRepository.findById(id)
    39→                .orElseThrow(() -> new EntityNotFoundException("User not found with id: " + id));
    40→        return new UserDTO(user);
    41→    }
    42→
    43→    public UserDTO getUserByUsername(String username) {
    44→        User user = userRepository.findByUsername(username)
    45→                .orElseThrow(() -> new EntityNotFoundException("User not found with username: " + username));
    46→        return new UserDTO(user);
    47→    }
    48→
    49→    public UserDTO createUser(CreateUserRequest request) {
    50→        if (userRepository.existsByUsername(request.getUsername())) {
    51→            throw new IllegalArgumentException("Username already exists");
    52→        }
    53→        if (userRepository.existsByEmail(request.getEmail())) {
    54→            throw new IllegalArgumentException("Email already exists");
    55→        }
    56→
    57→        User user = new User();
    58→        user.setUsername(request.getUsername());
    59→        user.setEmail(request.getEmail());
    60→        user.setPassword(passwordEncoder.encode(request.getPassword()));
    61→        user.setFirstName(request.getFirstName());
    62→        user.setLastName(request.getLastName());
    63→        user.setRole(request.getRole() != null ? request.getRole() : Role.USER);
    64→
    65→        User savedUser = userRepository.save(user);
    66→        return new UserDTO(savedUser);
    67→    }
    68→
    69→    public UserDTO updateUser(Long id, CreateUserRequest request) {
    70→        User user = userRepository.findById(id)
    71→                .orElseThrow(() -> new EntityNotFoundException("User not found with id: " + id));
    72→
    73→        if (!user.getUsername().equals(request.getUsername()) &&
    74→                userRepository.existsByUsername(request.getUsername())) {
    75→            throw new IllegalArgumentException("Username already exists");
    76→        }
    77→        if (!user.getEmail().equals(request.getEmail()) &&
    78→                userRepository.existsByEmail(request.getEmail())) {
    79→            throw new IllegalArgumentException("Email already exists");
    80→        }
    81→
    82→        user.setUsername(request.getUsername());
    83→        user.setEmail(request.getEmail());
    84→        if (request.getPassword() != null && !request.getPassword().isEmpty()) {
    85→            user.setPassword(passwordEncoder.encode(request.getPassword()));
    86→        }
    87→        user.setFirstName(request.getFirstName());
    88→        user.setLastName(request.getLastName());
    89→        if (request.getRole() != null) {
    90→            user.setRole(request.getRole());
    91→        }
    92→
    93→        User savedUser = userRepository.save(user);
    94→        return new UserDTO(savedUser);
    95→    }
    96→
    97→    public void deleteUser(Long id) {
    98→        if (!userRepository.existsById(id)) {
    99→            throw new EntityNotFoundException("User not found with id: " + id);
   100→        }
   101→        userRepository.deleteById(id);
   102→    }
   103→
